// Build-only config for CI.
//
// Sites publishes with freebuff.open-next.config.ts (R2 incremental cache and
// Durable Object overrides). That file is generated by Freebuff Sites and is
// not checked in, so CI uses this stock config: it runs the same `next build`
// and the same Worker bundling, which is what catches a Next version falling
// out of the OpenNext support window or pg-cloudflare failing to resolve.
import { defineCloudflareConfig } from "@opennextjs/cloudflare";

export default defineCloudflareConfig({});
